# =============================================================================
# NEXTFLOW ENGINE FLAGS
# =============================================================================
# Only Nextflow engine flags (single-dash) go on the command line.
# All pipeline parameters (double-dash --param) are in params.json above.
NF_ENGINE=(
    -params-file "$PARAMS_JSON"
    -profile local
    -c "$RESOURCES_OVERRIDE"
    -w "$WORK_DIR"
)
if [ "${RUN_TOWER:-false}" = true ]; then
    NF_ENGINE+=( -with-tower )
fi
NF_RUN_NAME="${TRAIT}${RUN_TAG}_$(cat /proc/sys/kernel/random/uuid 2>/dev/null | tr -d '-' | cut -c1-8 || printf '%08x' $RANDOM)"
NF_ENGINE+=(
    -name "$NF_RUN_NAME"
    -with-report   "${RESULTS_BASE}/nextflow_report_${NF_RUN_NAME}.html"
    -with-trace    "${RESULTS_BASE}/nextflow_trace_${NF_RUN_NAME}.tsv"
    -with-timeline "${RESULTS_BASE}/nextflow_timeline_${NF_RUN_NAME}.html"
)
if [ "$RESUME" = 1 ]; then
    NF_ENGINE+=( -resume )
fi

# --- EXTRA FLAGS (pass-through from GUI's extra_flags fields) ---
# These are user-provided arbitrary Nextflow flags that can't go in params.json
# (they may include engine flags or override-specific params). Kept on the CLI
# so they take highest precedence over both params.json and config defaults.

echo "======================================================"
echo "Running Nextflow Single Phenotype: $TRAIT"
echo "SLURM TASK ID     : ${SLURM_ARRAY_TASK_ID:-n/a}"

echo "Profile           : local"
echo "Trait             : $TRAIT"
echo "Alignments        : $ALI_DIR"
echo "Output            : $RESULTS_BASE"
echo "Work dir          : $WORK_DIR"
echo "Params file       : $PARAMS_JSON"

echo "Resuming?         : $([ "$RESUME" = 1 ] && echo yes || echo 'no (clean run)')"
echo "======================================================"

nextflow run "${REPO_DIR}/main.nf" "${NF_ENGINE[@]}"

if [ -f "${RESULTS_BASE}/low_contrasts.skip" ]; then
    echo "Warning: Skipped '${TRAIT}': too few foreground contrasts."
    exit 0
fi

echo "Success: Completed $TRAIT"
